func:
// SINGLE SOURCE OF TRUTH for all configuration defaults. Every other
// node reads flow.get('config') and must NOT re-default values — change a
// default here and it applies everywhere.
var defaults = {
    // --- comfort / safe ---
    targetTemp: 23,            // AC setpoint while running (°C)
    tempOnThreshold: 26,       // turn on when inside rises to this (°C)
    timeOnHour: 9,             // operating window start (hour)
    timeOffHour: 19,           // operating window end (hour)
    mode: 'cool',
    fanSpeed: 'auto',
    blow: 'on',                // X-Fan: dry the coil after shutdown
    outsideColdBelow: 20,      // outside < this → raise on-threshold (vent instead)
    outsideColdAdjust: 3,      //   by +N °C
    outsideHotAbove: 30,       // outside > this → lower on-threshold (cool earlier)
    outsideHotAdjust: 2,       //   by -N °C
    ventMargin: 2,             // outside < inside - margin → venting advisory
    // --- full writeable device parameter set (asserted on every command) ---
    temperatureUnit: 'celsius',
    lights: 'on',
    air: 'off',
    health: 'off',
    sleep: 'off',
    swingHor: 'default',
    swingVert: 'default',
    quiet: 'off',
    turbo: 'off',
    powerSave: 'off',
    safetyHeating: 'off',
    // --- critical: battery & compressor protection ---
    socOnThreshold: 70,        // start only above this SOC (%)
    socOffThreshold: 65,       // stop below this SOC (%)
    voltageOnThreshold: 53.5,  // PV-surplus voltage gate (V)
    onDelay: 60,               // conditions sustained before ON (s)
    offDelay: 60,              // conditions lost before OFF (s)
    minOnTime: 300,            // minimum runtime once on (s)
    minOffTime: 180            // minimum off before restart (s)
};
var saved = flow.get('config', 'persistent');
var config = Object.assign({}, defaults, saved || {});
flow.set('config', config);
flow.set('config', config, 'persistent');
if (!flow.get('acState')) {
    flow.set('acState', {power:false,manualMode:false,conditionsMetSince:null,conditionsNotMetSince:null,lastOnAt:0,lastOffAt:0});
}
flow.set('currentValues', {soc:0,batteryVoltage:0,batteryState:'Unknown',batterySystemState:'Unknown',batterySystemStateNum:-1,temperature:0,tempReceived:false,outsideTemp:0,outsideTempReceived:false});
node.status({fill:'green',shape:'dot',text:'Config loaded'});
msg.payload = config;
return msg;

// Static help texts. Dashboard 2.0 ui-text renders msg.payload, so the
// warning + manual hint are pushed as payloads.
node.send([
    { payload: '⚠️ These settings protect the battery and compressor. Wrong values can deep-discharge the battery or damage the AC. Unlock to change.' },
    { payload: 'ℹ️ Buttons only active when Manual mode is on.' }
]);
return null;

// Feeds the overview gauges + trend charts from currentValues/acState.
var v = flow.get('currentValues') || {};
var s = flow.get('acState') || {};
var inside  = v.tempReceived ? v.temperature : null;
var outside = v.outsideTempReceived ? v.outsideTemp : null;
var voltage = v.batteryVoltage || 0;
var soc = v.soc || 0;
var power = s.power ? 100 : 0;
return [
    outside !== null ? { payload: parseFloat(outside.toFixed(1)) } : null,
    voltage > 0 ? { payload: parseFloat(voltage.toFixed(2)) } : null,
    [
        inside !== null ? { payload: parseFloat(inside.toFixed(1)), topic: 'Inside' } : null,
        outside !== null ? { payload: parseFloat(outside.toFixed(1)), topic: 'Outside' } : null
    ],
    [
        { payload: Math.round(soc), topic: 'SOC %' },
        { payload: power, topic: 'AC on' }
    ]
];

var values = flow.get('currentValues') || {soc:0,batteryVoltage:0,batteryState:'Unknown',batterySystemState:'Unknown',batterySystemStateNum:-1,temperature:0,tempReceived:false,outsideTemp:0,outsideTempReceived:false};

var path = msg.path || msg.topic || '';

if (path.indexOf('Battery SOC') !== -1) {
    values.soc = (msg.payload !== null && msg.payload !== undefined) ? Number(msg.payload) : 0;
}
else if (path.indexOf('Battery State') !== -1) {
    var sysState = Number(msg.payload);
    var sysNames = {0:'Idle',1:'Charging',2:'Discharging'};
    values.batterySystemState    = sysNames[sysState] || ('State:' + sysState);
    values.batterySystemStateNum = sysState;
}
else if (path.indexOf('Battery Voltage') !== -1) {
    values.batteryVoltage = (msg.payload !== null && msg.payload !== undefined) ? Number(msg.payload) : 0;
    var v = values.batteryVoltage;
    if      (v >= 56.0) { values.batteryState = 'Absorption'; }
    else if (v >= 53.5) { values.batteryState = 'Float';      }
    else if (v >  0)    { values.batteryState = 'Bulk';       }
    else                { values.batteryState = 'Unknown';    }
}
else if (path.indexOf('Ruuvi Inside') !== -1) {
    if (msg.payload !== null && msg.payload !== undefined) {
        values.temperature  = Number(msg.payload);
        values.tempReceived = true;
    }
}
else if (path.indexOf('Ruuvi Outside') !== -1) {
    if (msg.payload !== null && msg.payload !== undefined) {
        values.outsideTemp         = Number(msg.payload);
        values.outsideTempReceived = true;
    }
}

flow.set('currentValues', values);

var inStr   = values.tempReceived        ? values.temperature.toFixed(1) + 'C' : '---';
var outStr  = values.outsideTempReceived ? values.outsideTemp.toFixed(1) + 'C' : '---';
var voltStr = values.batteryVoltage > 0  ? values.batteryVoltage.toFixed(2) + 'V' : '?V';
node.status({text:'SOC:' + Math.round(values.soc||0) + '% ' + voltStr + ' ' + (values.batteryState||'?') + ' In:' + inStr + ' Out:' + outStr});

return {payload: values};

// Pure presentation: maps currentValues to the dashboard widgets. The
// status line + countdown come straight from the controllerStatus that
// 'Main Logic' publishes — single source of truth, no duplicated logic.
var values = msg.payload || {};
var state  = flow.get('acState') || {};

var soc     = (values.soc !== undefined)            ? values.soc            : 0;
var temp    = (values.temperature !== undefined)    ? values.temperature    : 0;
var voltage = (values.batteryVoltage !== undefined) ? values.batteryVoltage : 0;
var battSt  = values.batteryState || '?';
var outside = values.outsideTempReceived ? values.outsideTemp : null;

var socMsg  = {payload: Math.round(soc)};
var tempMsg = {payload: parseFloat(temp.toFixed(1))};
var battDisplay = voltage > 0 ? battSt + ' (' + voltage.toFixed(2) + 'V)' : battSt;
var battStateMsg = {payload: battDisplay};
var acStatusMsg  = {payload: state.power ? 'ON' : 'OFF'};
var modeTextMsg  = {payload: state.manualMode ? 'MANUAL' : 'AUTOMATIC'};
var outsideTempMsg = {payload: outside !== null ? outside.toFixed(1) + '°C' : 'no sensor'};

var ctrl = global.get('controllerStatus') || {message: 'Starting…', etaSeconds: 0, since: Date.now()};
var statusText = ctrl.message || '';
if (ctrl.etaSeconds > 0) {
    var remain = Math.max(0, Math.ceil(ctrl.etaSeconds - (Date.now() - (ctrl.since || Date.now())) / 1000));
    if (remain > 0) statusText += ' ' + remain + 's';
}
var statusMsg = {payload: statusText};

return [socMsg, tempMsg, battStateMsg, acStatusMsg, modeTextMsg, statusMsg, outsideTempMsg];

// Decides when the AC turns on/off from PV surplus + temperature, and
// publishes a single controllerStatus (read by the Node-RED status text and
// the simulator dashboard). All tunables come from flow.config (see
// 'Config Init' for the single source of defaults) — no inline defaults.
var config = flow.get('config') || {};
var values = flow.get('currentValues') || {};
var state  = flow.get('acState') || {};
var now = Date.now();

// Sim clock override (test tooling, GLOBAL context). Only the time-of-day
// gate uses it; Date.now() (delays / min-times) stays real.
var simClock = global.get('simClock');
var hour = (simClock && simClock.enabled) ? Number(simClock.hour) : new Date().getHours();

var soc      = values.soc || 0;
var inside   = (values.temperature !== undefined) ? values.temperature : 0;
var voltage  = values.batteryVoltage || 0;
var stateNum = values.batterySystemStateNum;
var outside  = values.outsideTempReceived ? values.outsideTemp : null;

function setCtrl(phase, message, eta) {
    global.set('controllerStatus', {phase: phase, message: message, etaSeconds: Math.max(0, Math.round(eta || 0)), since: now});
}

// Manual mode: the controller stands down.
if (state.manualMode) {
    node.status({fill:'blue',shape:'dot',text:'Manual: ' + (state.power ? 'ON' : 'OFF')});
    setCtrl('manual', 'Manual mode — AC ' + (state.power ? 'on' : 'off'), 0);
    return null;
}

// Dynamic on-threshold: cooler outside raises it (give venting room), hotter
// lowers it. The inside threshold always wins once reached.
var effOn = config.tempOnThreshold;
if (outside !== null) {
    if (outside < config.outsideColdBelow) effOn += config.outsideColdAdjust;
    else if (outside > config.outsideHotAbove) effOn = Math.max(effOn - config.outsideHotAdjust, 16);
}
var ventHint = (outside !== null && outside < inside - config.ventMargin) ? ' · venting could help' : '';

var timeOK     = (hour >= config.timeOnHour && hour < config.timeOffHour);
var pvOK       = (stateNum === 0 || stateNum === 1);   // not discharging = PV surplus
var voltOK     = voltage >= config.voltageOnThreshold;
var socStartOK = soc >= config.socOnThreshold;
var socKeepOK  = soc >= config.socOffThreshold;
var tempOK     = inside >= effOn;

// ===== currently ON =====
if (state.power) {
    var onFor = (now - (state.lastOnAt || now)) / 1000;
    var off = [];
    if (!timeOK) off.push('quiet hours');
    if (!socKeepOK) off.push('SOC ' + Math.round(soc) + '% < ' + config.socOffThreshold + '%');
    if (!pvOK) off.push('battery discharging');

    if (off.length) {
        if (onFor < config.minOnTime) {
            var holdOn = config.minOnTime - onFor;
            node.status({fill:'green',shape:'dot',text:'Running, min on-time ' + Math.ceil(holdOn) + 's'});
            setCtrl('on', 'Running, holding for compressor', holdOn);
            return null;
        }
        if (!state.conditionsNotMetSince) { state.conditionsNotMetSince = now; flow.set('acState', state); }
        var offWaited = (now - state.conditionsNotMetSince) / 1000;
        if (offWaited >= config.offDelay) {
            state.power = false; state.lastOffAt = now; state.conditionsNotMetSince = null; flow.set('acState', state);
            node.status({fill:'red',shape:'dot',text:'OFF: ' + off.join(', ')});
            setCtrl('off', 'AC off — ' + off.join(', '), 0);
            return {payload: {action:'off', reason: off.join(', ')}};
        }
        node.status({fill:'yellow',shape:'dot',text:'OFF in ' + Math.ceil(config.offDelay - offWaited) + 's'});
        setCtrl('disarming', 'AC OFF (' + off.join(', ') + ') in', config.offDelay - offWaited);
        return null;
    }
    state.conditionsNotMetSince = null; flow.set('acState', state);
    node.status({fill:'green',shape:'dot',text:'Running | ' + voltage.toFixed(2) + 'V | SOC ' + Math.round(soc) + '%'});
    setCtrl('on', 'Running — SOC ' + Math.round(soc) + '% · ' + inside.toFixed(1) + '°C' + ventHint, 0);
    return null;
}

// ===== currently OFF =====
var blockers = [];
if (!timeOK) blockers.push('quiet hours');
if (!socStartOK) blockers.push('SOC ' + Math.round(soc) + '% < ' + config.socOnThreshold + '%');
if (!voltOK) blockers.push(voltage.toFixed(2) + 'V < ' + config.voltageOnThreshold + 'V');
if (!pvOK) blockers.push('battery discharging');
if (!tempOK) blockers.push('inside ' + inside.toFixed(1) + '°C < ' + effOn + '°C');

if (blockers.length) {
    state.conditionsMetSince = null; flow.set('acState', state);
    node.status({fill:'grey',shape:'ring',text:'Waiting: ' + blockers.join(' | ')});
    setCtrl('idle', 'Waiting — ' + blockers.join(', ') + ventHint, 0);
    return null;
}

// Compressor cooldown (min off-time) before a restart.
var offFor = (now - (state.lastOffAt || 0)) / 1000;
if (state.lastOffAt && offFor < config.minOffTime) {
    state.conditionsMetSince = null; flow.set('acState', state);
    node.status({fill:'yellow',shape:'ring',text:'Compressor cooldown ' + Math.ceil(config.minOffTime - offFor) + 's'});
    setCtrl('blocked', 'Compressor cooldown', config.minOffTime - offFor);
    return null;
}

if (!state.conditionsMetSince) { state.conditionsMetSince = now; flow.set('acState', state); }
var onWaited = (now - state.conditionsMetSince) / 1000;
if (onWaited >= config.onDelay) {
    state.power = true; state.lastOnAt = now; state.conditionsMetSince = null; state.conditionsNotMetSince = null; flow.set('acState', state);
    node.status({fill:'green',shape:'dot',text:'ON: SOC ' + Math.round(soc) + '% | ' + inside.toFixed(1) + '°C'});
    setCtrl('on', 'AC on — cooling to ' + config.targetTemp + '°C', 0);
    return {payload: {action:'on', reason:'SOC ' + Math.round(soc) + '% | ' + voltage.toFixed(2) + 'V | ' + inside.toFixed(1) + '°C'}};
}
node.status({fill:'yellow',shape:'dot',text:'ON in ' + Math.ceil(config.onDelay - onWaited) + 's'});
setCtrl('arming', 'AC ON in', config.onDelay - onWaited);
return null;

// Build the COMPLETE writeable parameter set on every command so the AC
// is driven to a fully known state (no partial writes). Only 'power'
// differs between on/off; everything else comes from flow.config.
var config = flow.get('config') || {};
var action = msg.payload.action;
var payload = {
    power:           action === 'on' ? 'on' : 'off',
    mode:            config.mode,
    temperatureUnit: config.temperatureUnit,
    temperature:     config.targetTemp,
    fanSpeed:        config.fanSpeed,
    air:             config.air,
    blow:            config.blow,
    health:          config.health,
    sleep:           config.sleep,
    lights:          config.lights,
    swingHor:        config.swingHor,
    swingVert:       config.swingVert,
    quiet:           config.quiet,
    turbo:           config.turbo,
    powerSave:       config.powerSave,
    safetyHeating:   config.safetyHeating
};
node.status({fill: action === 'on' ? 'green' : 'red', shape:'dot', text: (action === 'on' ? 'ON @ ' + config.targetTemp + 'C' : 'OFF') + ' (full set)'});
return {topic: action, payload: payload};

var state = flow.get('acState') || {};
state.manualMode = msg.payload;
flow.set('acState', state);
if (!state.manualMode) {
    node.status({fill:'green',shape:'ring',text:'Automatic active'});
} else {
    node.status({fill:'blue',shape:'dot',text:'Manual active'});
}
var values = flow.get('currentValues') || {};
return {payload: values};

// Manual on/off — route the action through '→ Gree Command' so it sends
// the same COMPLETE writeable parameter set as the automatic path.
var state = flow.get('acState') || {};
var cmd   = msg.payload;
if (!state.manualMode) {
    node.status({fill:'yellow',shape:'ring',text:'Enable Manual mode first!'});
    return null;
}
var now = Date.now();
if (cmd === 'on') { state.power = true; state.lastOnAt = now; }
else if (cmd === 'off') { state.power = false; state.lastOffAt = now; }
flow.set('acState', state);
node.status({fill: cmd === 'on' ? 'green' : 'red', shape:'dot', text: 'Manual ' + (cmd === 'on' ? 'ON' : 'OFF')});
var values = flow.get('currentValues') || {};
return [{payload: {action: cmd}}, {payload: values}];

// Persists one config key from a dashboard widget. String keys pass
// through; numeric keys are validated; CRITICAL keys are gated behind the
// 'Unlock critical settings' switch so they can't be changed by accident.
var config = flow.get('config') || {};
var key = msg.topic;
if (!key) { return null; }

var STRING_KEYS = ['mode', 'fanSpeed', 'blow'];
var CRITICAL = ['socOnThreshold','socOffThreshold','voltageOnThreshold','onDelay','offDelay','minOnTime','minOffTime'];

if (CRITICAL.indexOf(key) !== -1 && !flow.get('criticalUnlocked')) {
    node.status({fill:'red',shape:'ring',text:'🔒 Unlock critical settings to change ' + key});
    return null;
}

var value;
if (STRING_KEYS.indexOf(key) !== -1) {
    value = String(msg.payload);
} else {
    value = Number(msg.payload);
    if (!Number.isFinite(value)) { node.status({fill:'red',shape:'dot',text:'Invalid value for ' + key}); return null; }
}

if (key === 'socOffThreshold' && value >= config.socOnThreshold) {
    node.status({fill:'red',shape:'dot',text:'OFF-SOC must be < ON-SOC (' + config.socOnThreshold + '%)'}); return null;
}
if (key === 'socOnThreshold' && value <= config.socOffThreshold) {
    node.status({fill:'red',shape:'dot',text:'ON-SOC must be > OFF-SOC (' + config.socOffThreshold + '%)'}); return null;
}
if (key === 'timeOnHour' && value >= config.timeOffHour) {
    node.status({fill:'red',shape:'dot',text:'From must be < Until (' + config.timeOffHour + 'h)'}); return null;
}
if (key === 'timeOffHour' && value <= config.timeOnHour) {
    node.status({fill:'red',shape:'dot',text:'Until must be > From (' + config.timeOnHour + 'h)'}); return null;
}
if (key === 'tempOnThreshold' && value < config.targetTemp) {
    node.status({fill:'red',shape:'dot',text:'Turn-on temp must be ≥ target (' + config.targetTemp + '°C)'}); return null;
}
if (key === 'targetTemp' && value > config.tempOnThreshold) {
    node.status({fill:'red',shape:'dot',text:'Target must be ≤ turn-on temp (' + config.tempOnThreshold + '°C)'}); return null;
}
if (key === 'outsideColdBelow' && value >= config.outsideHotAbove) {
    node.status({fill:'red',shape:'dot',text:'Cold-below must be < hot-above (' + config.outsideHotAbove + '°C)'}); return null;
}
if (key === 'outsideHotAbove' && value <= config.outsideColdBelow) {
    node.status({fill:'red',shape:'dot',text:'Hot-above must be > cold-below (' + config.outsideColdBelow + '°C)'}); return null;
}
if (['onDelay','offDelay','minOnTime','minOffTime','ventMargin','outsideColdAdjust','outsideHotAdjust'].indexOf(key) !== -1 && value < 0) {
    node.status({fill:'red',shape:'dot',text: key + ' must be ≥ 0'}); return null;
}

config[key] = value;
flow.set('config', config);
flow.set('config', config, 'persistent');
node.status({fill:'green',shape:'dot',text: key + ' = ' + value + ' ✓'});
return null;

// Gate for the critical config parameters. 'Save Config' refuses to write
// critical keys unless this is true.
flow.set('criticalUnlocked', !!msg.payload);
node.status({fill: msg.payload ? 'red' : 'green', shape: 'dot', text: msg.payload ? '⚠️ Critical UNLOCKED' : '🔒 Critical locked'});
return null;
